WFJ.Data.add("gossip", {
  ["65002d110a8a4429"] = { "Le tue azioni ci disonorano tutti, {class}. Mi addolora doverti riempire di botte!", "." },
  ["650bcd87333d3c6f"] = { "{name} ha assaltato la segheria!", "." },
  ["650cdeab120f87d3"] = { "Cosa ti porta al ⟦Nethergarde Keep=Forte di Guardiafatua⟧, {race}?", "." },
  ["6511dd061fc4c28d"] = { "Dove vuoi volare?", "." },
  ["6515c9041fba6d63"] = { "Gradisce qualcos'altro da mangiare, signore?", "." },
  ["651be20f5c5c07b7"] = { "Non proseguire! Torna indietro, torna indietro finché sei in tempo!", "." },
  ["651ef3d12d09470c"] = { "Un altro braccatore, mmh. Dubito che la tua abilità sia grande quanto la mia, quindi forse posso insegnarti qualche tecnica come si deve.", "." },
  ["65242f6efac27b67"] = { "Sono Kilram, maestro dell'ascia.", "." },
  ["653248de7742106c"] = { "Sei finito, Mulv!", "." },
  ["6533e0b66f6a1536"] = { "Vieni a dare un'occhiata alla mia merce finché puoi. Restiamo qui tutta la settimana, e poi partiamo per qualche terra lontana.", "." },
  ["65343d0ee23a4fc6"] = { "Purtroppo c'è poco che io possa insegnare a qualcuno con la tua esperienza, <amico/amica> <mio/mia>. Cerca l'elfa della notte ⟦Sylvanna Forestmoon=Sylvanna Erbaluna⟧, che risiede nella ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧ di Darnassus.", "." },
  ["653b6d7a0b3e3c24"] = { "Le storie delle tue imprese si diffondono. Il tuo nome non ci è sconosciuto, {name}.", "." },
  ["653d3d8ee8bef3d1"] = { "Giù di morale", "." },
  ["654d69eb630c486c"] = { "{name} ha difeso la miniera!", "." },
  ["655e60c78b39614c"] = { "Quel kodo è proprio una bellezza. Aspetta un attimo, dove sono i miei occhiali bifocali? Forse dovresti esaminare la bestia al posto mio.", "." },
  ["655eefcd311df94c"] = { "Spaccalo!", "." },
  ["656363e66840155e"] = { "Davvero astuto il modo in cui sei <entrato/entrata> qui, {name}.\n\nCosa? <Sorpreso/Sorpresa> che io conosca il tuo nome? Sono un demone, è quello che facciamo. Conosco anche il tuo vero nome, quindi faresti meglio a comprare qualcosa di costoso.", "." },
  ["6567b9db96cd0c53"] = { "Perché proprio ora, {race}? Proprio non lo capisco. C'è così tanto lavoro da fare...", "." },
  ["656c468dc0ea7934"] = { "Usa il soffio gelido, imbecille!", "." },
  ["657bdc5001e1febf"] = { "%s banchetta!", "." },
  ["657e10318b751bb9"] = { "Alla fine è andato tutto bene.", "." },
  ["6582b8e77937f03d"] = { "Ogni stregone dovrebbe avere un vilsegugio al suo comando. Per quanto sia difficile da domare, i poteri che conferisce al suo padrone ne valgono ampiamente il prezzo.", "." },
  ["658b435d255a9ba7"] = { "La tua conoscenza è grande, <viaggiatore/viaggiatrice>. Devi imparare da qualcuno più saggio di me. Si raccontano molte storie sulla saggezza di Josef Gregorian. Puoi trovarlo a ⟦Undercity=Sepulcra⟧.", "." },
  ["658da537413da354"] = { "Argus è il fabbro di ⟦Goldshire=Borgodoro⟧. Di certo potrebbe insegnarti la professione di fabbro.", "." },
  ["6597da3762b301ae"] = { "Le stai facendo male!", "." },
  ["6598d101f2b123f1"] = { "Distruggete i registri prima che il bastione cada!", "." },
  ["659c4ff678e35211"] = { "C'è un istruttore di Forgiatura nella nostra grande casa, ⟦Thunder Bluff=Picco del Tuono⟧, a nord. Se cerchi questo sapere, vai là e chiedi indicazioni a uno dei Guardiani del Picco.", "." },
  ["65a66e51ff7914d5"] = { "Da questa fonte raccoglierò le acque sacre con cui unirò il sangue dei druidi caduti.", "." },
  ["65b4fedac1ceced2"] = { "Ho sentito che il nuovo Henweigh 6000 uscirà presto dalla catena di montaggio. Riesco a stento a contenere l'emozione!", "." },
  ["65bff5afef8d1e53"] = { "Maraudon è uno dei luoghi più sacri di ⟦Desolace=Desolanda⟧. Il grande tempio-caverna è il luogo di sepoltura di Zaetar, uno dei due figli immortali del semidio Cenarius. La leggenda narra che da Zaetar e dalla principessa degli elementali della terra, Theradras, nacque la sciagurata razza dei centauri. Si dice che, appena comparsi, i barbari centauri si rivoltarono contro il padre e lo uccisero. Alcuni credono che Theradras, nel suo dolore, abbia imprigionato lo spirito di Zaetar nella caverna tortuosa, usandone le energie per qualche scopo maligno.", "." },
  ["65c226e15a309d55"] = { "Gri'lek, del Sangue di Ferro\n\nIl viandante. Che la sua forza e la sua sete di battaglia attraversino le ere.\n\nGri'lek ora dimora lontano da qui. Un giorno, forse, tornerà...", "." },
  ["65c7f43374bbce7d"] = { "Ed ecco {name} che esce dalla prima curva!", "." },
  ["65d0fc419e382601"] = { "Potenziamento a unità campione!", "." },
  ["65d417aeb47358d6"] = { "Impari in fretta, {name}. Hai fatto un buon lavoro.", "." },
  ["65d6d5c1f91a11e7"] = { "Ma salve, {name}, cosa posso darti oggi?", "." },
  ["65d7094e82e3a089"] = { "Chi controlla la Stormpike Aid Station?", "." },
  ["65d8b0a519fdc9a4"] = { "Per imparare a conciare il cuoio e lavorare le pelli, vai a Orgrimmar, a nord. Uno degli Orgrimmar Grunt saprà indicarti la strada per l'istruttore di Conciatura.", "." },
  ["65e5099c3720c671"] = { "Certo che no, <caro/cara> <ragazzo/ragazza>. Voi tipi da «avventurieri» siete spesso vittime delle circostanze, in balia dei drammi politici che tendono a consumarsi tra il popolo e la corona.\n\nIl mio consiglio, quindi, è di cercare qualcos'altro, più precisamente: una nuova carriera.\n\nQuesto mondo ha già abbastanza eroi.", "." },
  ["65e9eccafd53802a"] = { "Prendi quella testa e di sicuro farà prendere uno spavento a Daryl. Non che non se lo meriti, quel maledetto bastardo arrogante. Ma ah! Non vedo l'ora di vedere la sua faccia quando gliela mostrerai.", "." },
  ["65ebe1dcc258ce8b"] = { "Desidero questa ⟦Eternal Quintessence=Quintessenza Eterna⟧, duca Idraxis", "." },
  ["65f1b69b261e6f07"] = { "Come va la classifica dei regali? Chi è il più popolare?", "." },
  ["65f7310425381421"] = { "La Frostwolf Relief Hut è sotto attacco! Se nessuno interviene, l'⟦Alliance=Alleanza⟧ la conquisterà!", "." },
  ["65fb9e12815e2353"] = { "Guardate il sangue che penetra nella neve, figli miei. L'elementale sarà legato a noi!", "." },
})
